function uiGuidance(file, gaps) {
  const ui = gaps.ui;
  // The guidance below names ui.framework and ui.testingLibrary, so the file has to
  // use THAT framework: firing on a vue import in a react-first repo would tell the
  // model to render a vue module with @testing-library/react. react and preact are
  // the one pair that answer for each other — preact/compat aliases the "react"
  // specifier, so a preact repo's own components import it under that name.
  const fw = String((ui && ui.framework) || '').trim().toLowerCase();
  // sanitised, because `framework` arrives as JSON and is spliced into a RegExp
  const pkgs = (fw === 'react' || fw === 'preact') ? 'react|preact' : fw.replace(/[^a-z]/g, '');

  const importsFramework = () => {
    if (!pkgs) return false;
    // The WHOLE file, not a window. The old 2000-character limit missed every
    // component whose import sat behind a licence header or a block of type
    // declarations — i.e. exactly the files a company actually ships. The ceiling
    // here only bounds a caller that hands us a bundle: the sidecar reads at most
    // 24 000 characters into `source` (repo.readFileSafe), so it never binds.
    const src = (typeof gaps.source === 'string' ? gaps.source : '').slice(0, 200000);

    // Comments come out before matching. A file that merely MENTIONS the framework —
    // a note, a commented-out import, a JSDoc `@type {import('react').FC}` — does not
    // use it, and dressing it up as a component sends the model looking for a DOM
    // that will never exist. Strings need no scanner: the shapes below require a
    // statement boundary, and a specifier quoted inside someone else's string sits in
    // the middle of an expression, never at one.
    const lines = [];
    let inBlock = false;
    for (let raw of src.split('\n')) {
      if (inBlock) {
        const close = raw.indexOf('*/');
        if (close < 0) continue;
        inBlock = false;
        raw = raw.slice(close + 2);
      }
      // `//` ends the line — unless it is the `//` of a URL, which would cut real code
      const slashes = raw.match(/(^|[^:])\/\//);
      if (slashes) raw = raw.slice(0, slashes.index + slashes[1].length);
      const open = raw.indexOf('/*');
      if (open >= 0) {
        const close = raw.indexOf('*/', open + 2);
        if (close >= 0) raw = raw.slice(0, open) + ' ' + raw.slice(close + 2);
        // Only a block comment that OPENS a line is followed across lines. A `/*`
        // appearing mid-line may be inside a string literal, and treating that as a
        // comment would swallow the rest of the file — a silent miss, the very bug
        // this rewrite exists to remove. Erring towards detection is the safe side.
        else if (!raw.slice(0, open).trim()) { inBlock = true; continue; }
      }
      if (raw.trim().charAt(0) === '*') continue; // JSDoc continuation line
      lines.push(raw);
    }
    const code = lines.join('\n');

    const spec = "['\"](?:" + pkgs + ")['\"]";
    // `import <clause> from 'react'`. The clause may contain neither a quote, a
    // backtick nor a semicolon, so one match can never run across the neighbouring
    // statement — which is what makes the type-only verdict below trustworthy.
    // The {0,2000} bound is not cosmetic: an unbounded lazy run turns this quadratic
    // (measured 1.2 s on 200 000 characters of quote-free `import` lines) because
    // every candidate start rescans to the end of the file. No real import clause is
    // anywhere near 2000 characters — react's entire public API is ~40 names.
    const esm = new RegExp("(?:^|[;\\n])[ \\t]*import\\s+([^'\"`;]{0,2000}?)from\\s*" + spec, 'g');
    // Type imports are erased at compile time: such a file borrows the framework's
    // SIGNATURES (a props interface, a ReactNode parameter) and renders nothing.
    const typeOnly = (clause) => {
      const c = clause.trim();
      if (/^type\b/.test(c)) return true;
      const named = c.match(/^\{([\s\S]*)\}$/);
      if (!named) return false; // a default or namespace binding is a value
      const parts = named[1].split(',').map((s) => s.trim()).filter(Boolean);
      return parts.length > 0 && parts.every((p) => /^type\s/.test(p));
    };
    // every match, not the first: a type-only import must not mask a real one below it
    let m;
    while ((m = esm.exec(code))) if (!typeOnly(m[1])) return true;
    // Side-effect import, CommonJS and dynamic import: all three are value imports by
    // construction and have no clause to inspect. `require` was the reported miss —
    // a CommonJS component used to be handed logic-test guidance, and the model then
    // wrote assertions about internals instead of about rendered output.
    if (new RegExp("(?:^|[;\\n])\\s*import\\s*" + spec).test(code)) return true;
    if (new RegExp("\\brequire\\(\\s*" + spec + "\\s*\\)").test(code)) return true;
    if (new RegExp("\\bimport\\(\\s*" + spec + "\\s*\\)").test(code)) return true;
    return false;
  };

  // extension first: a .tsx file never pays for the scan
  const isComponent = /\.[jt]sx$/.test(String(file || '')) || importsFramework();
  return (ui && isComponent) ? '\nThis file is a UI COMPONENT (' + ui.framework + '). Component-testing rules:'
    + '\n- Render it with ' + (ui.testingLibrary || "the repo's established component-testing approach") + ' and assert on VISIBLE behavior: roles, accessible names, text, attributes — never on implementation internals or state.'
    + '\n- Prefer accessible queries (getByRole, getByLabelText, getByText) over test ids.'
    + (ui.userEvent ? "\n- Simulate clicks/typing with @testing-library/user-event and assert the resulting DOM and callback invocations." : '')
    + (ui.jestDom ? '\n- jest-dom matchers (toBeInTheDocument, toBeDisabled, toHaveAttribute, ...) are available.' : '')
    + '\n- Cover props/variants, conditional rendering branches, and event-handler callbacks (pass vi/jest mocks as handlers).'
    + '\n- Do not snapshot; do not shallow-render; do not reach into component internals.'
    : '';
}
function commonTestRules(maxFiles = 2) {
  return '\n- Tests must be deterministic (no timing races, no network, no randomness without seeding).'
    + '\n- Code must satisfy strict linters: no `any` types, no unused imports or variables, no non-null assertions.'
    + '\n- Import the module under test via its public path exactly as existing tests do.'
    + '\n- Never inspect function source code (no fn.toString() introspection).'
    + '\n- No snapshot tests. Prefer precise value assertions.'
    + '\n- The tests MUST pass against the CURRENT implementation of the source file.'
    + (maxFiles === 1 ? '\n- Output EXACTLY ONE test file.' : '\n- Output at most ' + maxFiles + ' test files.');
}
function covBuildPrompt(gaps, file) {
  const ext = (file.match(/\.[cm]?[jt]sx?$/) || ['.ts'])[0];
  const u = gaps.uncovered || {};
  const fullyUncovered = u.lines === 'all';
  const nothingToCover = !gaps.needsBootstrap
    || (!fullyUncovered && (!u.lines || !u.lines.length) && (!u.functions || !u.functions.length) && (!u.branches || !u.branches.length));
  const base = gaps.testPath.replace(/\.(test|spec)\.[cm]?[jt]sx?$/, '').replace(/\.[cm]?[jt]sx?$/, '');
  const roundSuffix = (gaps.rounds || 0) > 0 ? '-r' + ((gaps.rounds || 0) + 1) : '';
  const targetPath = base + '.mac-cov' + roundSuffix + '.test' + ext;
  if (nothingToCover) return { skip: true, reason: gaps.needsBootstrap ? 'file fully covered' : 'already executed by tests — mutant loop takes it from here', targetPath, existingTestPath: gaps.testPath, existingTestExists: gaps.testExists };
  const constraints = (gaps.constraints || []).map(c => '- ' + c).join('\n');
  const ui = uiGuidance(file, gaps);
  const system = 'You are an expert JavaScript/TypeScript test engineer writing ' + gaps.runner + ' tests to INCREASE LINE COVERAGE of one source file. Reply ONLY with JSON: {"tests":[{"path":"...","content":"full test file content"}]}. Create NEW test files only — never modify existing files. Preferred new file path: ' + targetPath + '. Rules:' + commonTestRules()
    + ui
    + (constraints ? '\nTeam constraints:\n' + constraints : '');
  const prompt = 'SOURCE FILE: ' + gaps.path + ' (package: ' + gaps.packageJson + ')\n'
    + String(gaps.source || '').slice(0, 14000)
    + '\n\nUNCOVERED: ' + (fullyUncovered ? 'ENTIRE FILE (never imported by any test)' :
        'lines ' + JSON.stringify((u.lines || []).slice(0, 120))
        + '; functions ' + JSON.stringify((u.functions || []).slice(0, 30))
        + '; branches ' + JSON.stringify((u.branches || []).slice(0, 40)))
    + '\n\nEXISTING TEST FILE (' + gaps.testPath + ', style reference — do not rewrite it):\n'
    + String(gaps.existingTest || '(none)').slice(0, 6000)
    + '\n\nWrite tests that execute the uncovered lines/functions/branches. JSON only.';
  return { system, prompt, json: true, maxTokens: 6000, temperature: 0.3, stage: 'improving_coverage', stageDetail: 'writing tests for uncovered code', targetPath, existingTestPath: gaps.testPath, existingTestExists: gaps.testExists };
}
return [{ json: covBuildPrompt($json, $('Start Iteration').first().json.file) }];

function covParseTests(resp, plan) {
  let tests = (resp.ok && resp.json && Array.isArray(resp.json.tests)) ? resp.json.tests : [];
  tests = tests
    .filter(t => t && typeof t.content === 'string' && t.content.trim().length > 10)
    .slice(0, 2)
    .map((t, i) => {
      let p = (typeof t.path === 'string' ? t.path : '').replace(/^\.?\//, '');
      const safe = /((^|\/)(tests?|__tests__|spec)\/|\.(test|spec)\.[cm]?[jt]sx?$)/.test(p)
        && /\.[cm]?[jt]sx?$/.test(p) && !p.includes('..');
      const collides = p === plan.existingTestPath && plan.existingTestExists;
      if (!safe || collides) p = i === 0 ? plan.targetPath : plan.targetPath.replace('.test.', '-' + i + '.test.');
      return { path: p, content: t.content };
    })
    .filter((t, i, all) => all.findIndex(o => o.path === t.path) === i);
  return { tests, paths: tests.map(t => t.path), count: tests.length };
}
return [{ json: covParseTests($json, $('Cov: Build Prompt').first().json) }];

function covBuildRepair(fail, parsed, gaps, stage) {
  const filesTxt = parsed.tests.map(t => 'PATH: ' + t.path + '\n' + t.content.slice(0, 6000)).join('\n\n---\n\n');
  // Ask only for what the sub-graph can act on. "Cov: Write Repair" writes what came
  // back and nothing else, so an omitted file is NOT deleted — it keeps its failing
  // content, "Cov: Re-run Tests" stays red, and "Cov: Delete Broken Tests" then throws
  // away the files that WERE repaired along with it. Every path must come back; an
  // assertion that cannot be saved is dropped as a test CASE inside a returned file.
  const system = 'You are an expert test engineer. Tests you previously wrote FAIL against the current implementation. Fix them. Keep the SAME file paths. Reply ONLY with JSON: {"tests":[{"path":"...","content":"full corrected file content"}]}. Return EVERY file you were given, one entry per path, no renames and no new files. Omitting a file does not delete it: the failing version stays on disk, the whole run stays red, and every file you did repair is thrown away with it. If a test asserts wrong expected values, correct the expectations to match the real behavior of the source. If one test case cannot be fixed, delete that case and return the rest of the file; if a whole file is beyond saving, return it holding one small test that really passes against the source — never an empty file and never a skipped or placeholder test, because a file with no runnable test fails the run too.';
  const n = parsed.tests.length;
  const prompt = 'TEST RUNNER OUTPUT (failures):\n' + String(fail.summary || '').slice(0, 3500)
    + '\n\nYOUR TEST FILES:\n' + filesTxt
    + '\n\nSOURCE FILE ' + gaps.path + ' (for reference):\n' + String(gaps.source || '').slice(0, 10000)
    + '\n\nReply with corrected JSON now: all ' + n + (n === 1 ? ' file' : ' files')
    + ', on these exact paths: ' + parsed.tests.map(t => t.path).join(', ');
  return { system, prompt, json: true, maxTokens: 6000, temperature: 0.2, stage, stageDetail: 'repairing failing generated tests' };
}
return [{ json: covBuildRepair($json, $('Cov: Parse Tests').first().json, $('Coverage Gaps').first().json, 'improving_coverage') }];

function covParseRepair(resp, prev) {
  let tests = (resp.ok && resp.json && Array.isArray(resp.json.tests)) ? resp.json.tests : [];
  tests = tests
    .filter(t => t && typeof t.content === 'string' && t.content.trim().length > 10)
    .slice(0, prev.paths.length)
    .map((t) => ({ path: prev.paths.includes(t.path) ? t.path : null, content: t.content }));
  // fill the unrecognised paths from whatever is still unclaimed, in order
  const free = prev.paths.filter(p => !tests.some(t => t.path === p));
  tests = tests.map(t => (t.path ? t : { ...t, path: free.shift() || null })).filter(t => t.path);
  return { tests, paths: tests.map(t => t.path), count: tests.length };
}
return [{ json: covParseRepair($json, $('Cov: Parse Tests').first().json) }];

